  int nextCalls = 0;
  int previousCalls = 0;
  int playPauseCalls = 0;
  final List<Duration> seeks = <Duration>[];

  @override
  Future<void> next() async {
    nextCalls++;
  }

  @override
  Future<void> previous() async {
    previousCalls++;
  }

  @override
  Future<void> playPause() async {
    playPauseCalls++;
  }

  @override
  Future<void> seek(Duration position) async {
    seeks.add(position);
  }
}

